import {SAVE_VERSION,RULES_URL,referenceURL,exhaustionPenalty,walkingSpeed,abilityCheckBonus,saveBonus,attackBonus,shortRest,COINS,SHEET_TEXT,initiative,passivePerception,validDiceFormula,rollFeature,ABILITIES,SKILLS,CLASSES,XP,CONDITIONS,STORAGE_KEY,uid,mod,signed,proficiency,skillBonus,castingAbility,wikiURL,safeURL,demoCharacter,makeCharacter,parseBackup,rollDice,changeHP,longRest,levelUp,clamp,randomDie} from './model.js';
import {defaultCharacters,initialState} from './default-characters.js';
import {icon} from './icons.js';
import {itemIconMarkup,installItemIconFallbacks} from './item-icons.js';
import {isSheetFavorite,mountSheetLayout,refreshSheetLayout,toggleSheetSection,toggleSheetFavorite} from './sheet-layout.js';
import {landscape,campArt} from './art.js';
import {portraitMarkup} from './portrait.js';
import {openPortraitMaker} from './portrait-ui.js';
import {openSheetScanner} from './sheet-scan-ui.js';
import {SUBCLASSES,applyStartingOptions} from './catalog.js';
import {characterChoice,classPreview,catalogPicker,handleCatalogFilter,handleCatalogChoice,catalogBrowser,updateCatalogBrowser} from './catalog-ui.js';

installItemIconFallbacks();
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn = (action,label,cls='btn',attrs='') => `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const ext = (url,label,cls='') => safeURL(url) ? `<a href="${esc(safeURL(url))}" target="_blank" rel="noopener noreferrer" class="${cls}">${label}</a>` : `<span class="${cls}">${label}</span>`;
const fmt = n => Number(n).toLocaleString();
const routes = {sheet:['Character sheet','sheet'],inventory:['Inventory','bag'],spells:['Spellbook','book'],journal:['Adventure journal','journal'],dice:['Dice roller','dice'],wiki:['2024 compendium','compass'],settings:['Settings & backup','settings']};
let storageError = '';
let state;
try { const saved=localStorage.getItem(STORAGE_KEY);state=saved?parseBackup(saved):initialState(); }
catch { state=initialState();storageError='Your saved data could not be loaded. This is a temporary sheet. Export your existing browser data before saving over it, or import a backup in Settings.'; }
let storageBlocked = !!storageError;
let route = Object.hasOwn(routes,location.hash.slice(1))?location.hash.slice(1):'sheet';
let filter='All',query='',rollMode='normal',diceExpression='1d20',rollHistory=[],lastRoll=null;
let modalSubmit=null,installPrompt=null;
const character = () => state.characters.find(c=>c.id===state.activeId) || state.characters[0];
const modal = $('#modal');

function persist() {
  if (storageBlocked) { toast('This sheet is temporary. Export a backup to keep your changes.',true);return false; }
  try {const serialized=JSON.stringify(state);if(new Blob([serialized]).size>2000000)throw new Error('Storage limit');localStorage.setItem(STORAGE_KEY,serialized);storageError='';return true;}
  catch { storageError='Device storage is unavailable or full. Changes are in memory only. Export a backup in Settings before closing this page.';toast('Couldn’t save on this device. Export a backup before leaving.',true);return false; }
}
function commit(message='') { persist();render();if(message)toast(message); }
function toast(message,error=false) {
  const el=document.createElement('div');el.className=`toast${error?' error':''}`;el.innerHTML=icon(error?'flag':'check')+`<span>${esc(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),4800);
}
function navigate(next) { if(!Object.hasOwn(routes,next))return;route=next;query='';filter='All';location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true}); }
function sound(kind='roll') {
  if(!state.settings.sound)return;
  try {const Audio=window.AudioContext||window.webkitAudioContext;const ctx=new Audio();const notes=kind==='level'?[392,494,587,784]:[260,390];notes.forEach((hz,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type='square';o.frequency.value=hz;g.gain.setValueAtTime(.025,ctx.currentTime+i*.11);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.11+.12);o.connect(g);g.connect(ctx.destination);o.start(ctx.currentTime+i*.11);o.stop(ctx.currentTime+i*.11+.13);});setTimeout(()=>ctx.close(),1100);}catch{}
}
function setModal(title,body,onSubmit=null) {
  modalSubmit=onSubmit;
  modal.innerHTML=`<form id="modal-form"><header class="modal-header"><h2 id="modal-title">${title}</h2>${btn('close',icon('close'),'icon-btn','aria-label="Close dialog"')}</header><div class="modal-body">${body}<div id="form-error" role="alert" hidden></div></div></form>`;
  if(!modal.open)modal.showModal();
  modal.scrollTop=0;
  modal.querySelector('[autofocus], input:not([type="checkbox"]), textarea, select, button')?.focus({preventScroll:true});
}
const actions = (label='Save changes',extra='') => `<div class="modal-actions">${extra}${btn('close','Cancel','btn btn-ghost')}<button class="btn btn-primary" type="submit">${icon('check')}${esc(label)}</button></div>`;
function field(label,name,value='',type='text',extra='') { return `<label class="form-field ${extra.includes('data-full')?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`; }
function select(label,name,values,value,extra='') { return `<label class="form-field">${label}<select name="${name}" ${extra}>${values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`; }
const textarea = (label,name,value,rows=5,maxlength=20000) => `<label class="form-field full">${label}<textarea name="${name}" rows="${rows}" maxlength="${maxlength}">${esc(value)}</textarea></label>`;
const num = (data,key) => Number(data.get(key));
const textValue = (data,key) => String(data.get(key)||'').trim();
const sheetEntry = (key,label) => `data-sheet-entry="${esc(key)}" data-sheet-label="${esc(label)}"`;
const coinName = key => key[0].toUpperCase()+key.slice(1);
const coinStud = key => icon('stud',`coin-stud coin-stud-${key}`);
function renderCoinBalances(c) {
  return `<span class="coin-balances">${Object.entries(COINS).map(([key,unit])=>`<span class="coin-balance" data-denomination="${key}">${coinStud(key)}<strong>${fmt(c[key])}</strong><abbr title="${coinName(key)} pieces">${unit.toUpperCase()}</abbr></span>`).join('')}</span>`;
}
function empty(symbol,title,copy,action='',label='') { return `<div class="empty-state">${icon(symbol)}<h2>${title}</h2><p>${copy}</p>${action?btn(action,icon('plus')+label,'btn btn-primary'):''}</div>`; }
function pageHeading(title,buttons='') {return `<div class="page-heading"><div><h1>${esc(title)}</h1></div>${buttons?`<div class="heading-actions">${buttons}</div>`:''}</div>`;}

function renderChrome() {
  const c=character();
  $('#sidebar').innerHTML=`<a href="#sheet" class="brand" aria-label="Questlog home"><span class="brand-mark">${icon('dice')}</span><span class="brand-name">questlog<span style="color:#8a9c65">.</span></span></a><div class="brand-sub">YOUR POCKET ADVENTURE</div><div class="nav-label">ADVENTURE MENU</div><nav class="desktop-nav">${Object.entries(routes).slice(0,5).map(([key,[label,symbol]])=>btn('navigate',icon(symbol)+label,`nav-link${route===key?' active':''}`,`data-route="${key}" ${route===key?'aria-current="page"':''}`)).join('')}</nav><div class="nav-divider"></div><div class="nav-label">A LITTLE GUIDANCE</div>${btn('navigate',icon('compass')+'2024 compendium',`nav-link${route==='wiki'?' active':''}`,'data-route="wiki"')}<div class="sidebar-bottom"><div class="camp-card">${campArt()}<p>Even heroes need a break.</p><small>Rest up. The road can wait.</small>${btn('rest',icon('camp')+'Take a rest','', 'data-kind="short"')}</div><div class="sidebar-foot"><span>QUESTLOG / 2024 RULES</span>${btn('navigate',icon('settings'),'icon-btn','data-route="settings" aria-label="Settings and backup"')}</div></div>`;
  $('#topbar').innerHTML=`<div class="breadcrumb">Your adventures ${icon('chevron')} <strong>${routes[route][0]}</strong></div><a class="mobile-brand" href="#sheet">${icon('dice')}questlog<span style="color:#90a36b">.</span></a><div class="topbar-right"><span class="save-state" title="${storageError?'Changes are not saved':'Saved on this browser. Export a backup to move devices.'}"><span class="status-dot" style="${storageError?'background:#b77d58':''}"></span>${storageError?'Unsaved · export a backup':'Saved on this device'}</span>${btn('characters',`<span class="mini-avatar">${portraitMarkup(c)}</span><span>${esc(c.name.split(' ')[0])}</span>${icon('down')}`,'character-switch','aria-label="Switch or create a character"')}</div>`;
  const mobile = [['sheet','sheet','Sheet'],['inventory','bag','Pack'],['spells','book','Spells'],['journal','journal','Journal'],['dice','dice','Roll'],['more','more','More']];
  $('#mobile-nav').innerHTML=mobile.map(([key,sym,label])=>btn(key==='more'?'more':'navigate',icon(sym)+`<span>${label}</span>`,`${route===key||(key==='more'&&['wiki','settings'].includes(route))?'active':''}`,`data-route="${key}" ${route===key?'aria-current="page"':''}`)).join('');
}
function render() {
  renderChrome();
  const views={sheet:renderSheet,inventory:renderInventory,spells:renderSpells,journal:renderJournal,dice:renderDice,wiki:renderWiki,settings:renderSettings};
  $('#main').innerHTML=(storageError?`<div class="storage-warning">${esc(storageError)} ${btn('export','Export current sheet','btn btn-sm')}</div>`:'')+views[route]();
  if(route==='sheet')mountSheetLayout($('#main'),character());
  if(route==='wiki')updateCatalogBrowser($('#main'),true);
  document.title=`${routes[route][0]} · Questlog`;
}
function slotDots(slot,level,small=false) {return `<div class="slot-dots">${Array.from({length:slot.max},(_,i)=>btn('slot','',`slot-dot${i<slot.used?' used':''}`,`data-level="${level}" data-used="${i<slot.used?i:i+1}" aria-label="${i<slot.used?'Restore':'Use'} level ${level+1} spell slot ${i+1}" title="${i<slot.used?'Restore':'Use'} a spell slot"`)).join('')}</div>`;}
function renderHero(c) {
  return `<section class="hero" aria-label="${esc(c.name)}"><div class="hero-art">${landscape()}</div>${btn('edit-character',icon('edit'),'icon-btn hero-edit','aria-label="Edit character details"')}<div class="hero-content"><button type="button" class="avatar-frame portrait-button" data-action="portrait" aria-label="Make or edit character portrait" title="Make or edit portrait">${portraitMarkup(c)}<span class="portrait-edit-hint">${icon('edit')}</span><span class="level-badge">LVL ${String(c.level).padStart(2,'0')}</span></button><div class="hero-info"><div class="hero-kicker">THE ADVENTURE CONTINUES</div><h2>${esc(c.name)}</h2><div class="hero-meta"><span>${esc(c.race)}</span><span class="meta-dot">/</span>${ext(wikiURL(c.class),esc(c.class))}${c.subclass?`<span class="meta-dot">/</span><span>${esc(c.subclass)}</span>`:''}</div>${c.playerName?`<div class="hero-player">Played by ${esc(c.playerName)}</div>`:''}<div class="hero-tags"><span class="hero-tag">${esc(c.background)}</span><span class="hero-tag">${esc(c.alignment)}</span></div></div></div></section>`;
}
function renderSheet() {
  const c=character(),next=XP[c.level+1],pct=next?clamp((c.xp-XP[c.level])/(next-XP[c.level])*100,0,100):100;
  return pageHeading('Character Sheet',btn('rest',icon('moon')+'<span class="mobile-hide">Long </span>Rest','btn','data-kind="long"')+btn('level-up',icon('spark')+'Level up','btn btn-primary',''+(c.level>=20?'disabled':'')))+
    renderHero(c)+`<div class="xp-strip"><span class="xp-label">${icon('spark')}EXPERIENCE</span><div class="xp-progress" role="progressbar" aria-label="Progress to next level" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(pct)}"><div class="xp-fill" style="width:${pct}%"></div></div><span class="xp-value"><strong>${fmt(c.xp)}</strong> / ${next?fmt(next)+' XP':'MAX LEVEL'}</span>${btn('xp',icon('plus')+'Add XP','xp-add')}</div>`+
    `<p class="sheet-layout-help">${icon('star')}Star favorites to keep them visible when a section is collapsed. Tap a section title to collapse it.</p><section class="ability-section" data-sheet-section="abilities"><div class="section-heading"><h2>${icon('dice')}Ability scores</h2><div style="display:flex;align-items:center;gap:12px"><span class="hint">Tap a modifier to roll${c.exhaustion?' · Exhaustion −'+exhaustionPenalty(c):''}</span>${btn('abilities',icon('edit'),'icon-btn','aria-label="Edit ability scores"')}</div></div><div class="ability-grid" data-sheet-group>${Object.entries(ABILITIES).map(([key,label])=>btn('ability-roll',`<div class="ability-label">${label}</div>${icon('dice','roll-hint')}<div class="ability-mod">${signed(mod(c.stats[key]))}</div><span class="ability-score">${c.stats[key]}</span>`,'ability-card',`${sheetEntry(key,label)} data-key="${key}" aria-label="Roll a ${label} check, ${signed(abilityCheckBonus(c,key))}"`)).join('')}</div></section>`+
    `<div class="dashboard-grid"><div class="column"><section class="panel" data-sheet-section="combat"><div class="panel-heading"><h2>${icon('heart')}Ready for anything</h2>${btn('combat-edit','Edit stats','text-btn')}</div>${renderCombat(c)}</section><section class="panel" data-sheet-section="attacks"><div class="panel-heading"><h2>${icon('sword')}Attacks & actions</h2>${btn('attack',icon('plus'),'icon-btn','aria-label="Add an attack"')}</div>${c.attacks.length?c.attacks.map(a=>renderAttack(c,a)).join(''):empty('sword','Your next move','Add a weapon attack and its damage dice.','attack','Add attack')}${c.slots.some(s=>s.max)?`<div class="spell-peek" ${sheetEntry('spell-slots','Spell slots')}>${icon('spark')}Spell slots <strong>Level ${c.slots.findIndex(s=>s.max)+1}</strong>${slotDots(c.slots.find(s=>s.max),c.slots.findIndex(s=>s.max))}</div>`:''}</section></div><div class="column">${renderJournalPeek(c)}${renderPackPeek(c)}<div class="adventure-tip">${icon('leaf')}<div><strong>Adventure at your own pace.</strong>Your sheet saves as you go. The best stories take a few unexpected turns.</div></div></div></div>`+
    `<div class="skills-grid"><section class="panel" data-sheet-section="skills"><div class="panel-heading"><h2>${icon('dice')}Skills & saving throws</h2><span class="badge">PROFICIENCY ${signed(proficiency(c.level))}</span></div><div class="panel-body"><p class="skill-description">Tap a dot: untrained → proficient → expertise. Tap a bonus to roll.</p>${Object.entries(SKILLS).map(([name,key])=>`<div class="skill-row" ${sheetEntry('skill-'+name,name)}>${btn('skill-prof',`<span class="prof-dot ${c.expertise.includes(name)?'expert':c.skills.includes(name)?'active':''}"></span>`,'prof-toggle',`data-skill="${esc(name)}" aria-label="${esc(name)} proficiency: ${c.expertise.includes(name)?'expertise':c.skills.includes(name)?'proficient':'untrained'}. Tap to change."`)}<span class="skill-name">${name}</span><span class="skill-ability">${key}</span>${btn('skill-roll',signed(skillBonus(c,name)),'skill-roll',`data-skill="${esc(name)}" aria-label="Roll ${esc(name)}"`)}</div>`).join('')}<div class="nav-divider" style="margin:18px 0"></div>${Object.entries(ABILITIES).map(([key,name])=>`<div class="skill-row" ${sheetEntry('save-'+key,name+' saving throw')}>${btn('save-prof',`<span class="prof-dot ${c.saves.includes(key)?'active':''}"></span>`,'prof-toggle',`data-key="${key}" aria-label="Toggle ${name} saving throw proficiency" aria-pressed="${c.saves.includes(key)}"`)}<span class="skill-name">${name} save</span>${btn('save-roll',signed(saveBonus(c,key)),'skill-roll',`data-key="${key}" aria-label="Roll ${name} saving throw"`)}</div>`).join('')}</div></section><div class="column">${renderFeatures(c)}${renderEssentials(c)}${renderSheetDetails(c)}</div></div>`;
}
function featureCharges(f) {
  if(f.maxUses<=12)return Array.from({length:f.maxUses},(_,i)=>btn('feature-use','',`slot-dot${i<f.used?' used':''}`,`data-id="${f.id}" data-used="${i<f.used?i:i+1}" aria-label="${i<f.used?'Restore':'Use'} ${esc(f.name)} charge ${i+1}"`)).join('');
  return `<div class="feature-counter">${btn('feature-use',icon('minus'),'icon-btn',`data-id="${f.id}" data-used="${f.used+1}" ${f.used>=f.maxUses?'disabled':''} aria-label="Spend one ${esc(f.name)} point"`)}<strong>${f.maxUses-f.used} / ${f.maxUses}</strong>${btn('feature-use',icon('plus'),'icon-btn',`data-id="${f.id}" data-used="${f.used-1}" ${f.used<=0?'disabled':''} aria-label="Restore one ${esc(f.name)} point"`)}${btn('feature', 'Set amount','text-btn',`data-id="${f.id}"`)}</div>`;
}
function renderFeatures(c) {
  return `<section class="panel" data-sheet-section="features"><div class="panel-heading"><h2>${icon('star')}Features & resources</h2>${btn('feature',icon('plus'),'icon-btn','aria-label="Add a feature or resource"')}</div><div class="features-list">${c.features.length?c.features.map(f=>`<div class="action-row" ${sheetEntry(f.id,f.name)}><div class="item-symbol">${icon('star')}</div><div class="action-info"><strong>${ext(referenceURL(f.wiki,c.class),esc(f.name)+' '+icon('external'))}</strong><small>${esc(f.description)}</small>${f.maxUses?`<div class="feature-uses">${featureCharges(f)}<small>${f.maxUses-f.used} / ${f.maxUses} remaining · Resets: ${f.reset==='manual'?'manually':f.reset+' rest'}${f.reset==='long'&&f.shortRestRecovery?' · +'+f.shortRestRecovery+' use(s) / short rest':''}</small></div>`:''}${f.rollFormula?btn('feature-roll',icon('dice')+esc(f.rollFormula)+(f.maxUses?' · Use & roll':' · Roll'),'btn btn-sm feature-roll',`data-id="${f.id}" ${f.maxUses&&f.used>=f.maxUses?'disabled':''} aria-label="Roll ${esc(f.name)}${f.maxUses?' and spend one use':''}"`):''}</div>${btn('feature',icon('edit'),'icon-btn',`data-id="${f.id}" aria-label="Edit ${esc(f.name)}"`)}</div>`).join(''):empty('star','A few special talents','Track class features, feats, maneuvers, and limited-use abilities.','feature','Add feature')}</div></section>`;
}
function renderEssentials(c) {
  return `<section class="panel" data-sheet-section="essentials"><div class="panel-heading"><h2>${icon('eye')}Senses & essentials</h2>${btn('essentials',icon('edit'),'icon-btn','aria-label="Edit senses and passive Perception"')}</div><div class="panel-body"><div class="skill-row" ${sheetEntry('perception','Passive Perception')}><span class="skill-name">Passive Perception</span><strong>${passivePerception(c)}</strong></div><div class="skill-row" ${sheetEntry('hit-dice','Hit dice remaining')}><span class="skill-name">Hit dice remaining</span><strong>${c.hitDice} / ${c.level} d${c.hitDie}</strong></div><div class="skill-row" ${sheetEntry('campaign','Campaign')}><span class="skill-name">Campaign</span><span class="essential-value">${esc(c.campaign)}</span></div>${c.playerName?`<div class="skill-row" ${sheetEntry('player','Player')}><span class="skill-name">Player</span><span class="essential-value">${esc(c.playerName)}</span></div>`:''}<dl class="sheet-copy"><div ${sheetEntry('senses','Senses')}><dt>Senses</dt><dd>${c.senses?esc(c.senses):'Add darkvision, special senses, and their ranges.'}</dd></div></dl><p class="data-caption">Armor, spell slots, and class choices are editable. Follow your table’s rules.</p></div></section>`;
}
function renderTextPanel(c,title,symbol,action,keys) {
  return `<section class="panel" data-sheet-section="${action}"><div class="panel-heading"><h2>${icon(symbol)}${title}</h2>${btn(action,icon('edit'),'icon-btn',`aria-label="Edit ${title.toLowerCase()}"`)}</div><div class="panel-body"><dl class="sheet-copy">${keys.map(key=>`<div ${sheetEntry(key,SHEET_TEXT[key])}><dt>${SHEET_TEXT[key]}</dt><dd class="${c[key]?'':'unset'}">${c[key]?esc(c[key]):'Not recorded yet.'}</dd></div>`).join('')}</dl></div></section>`;
}
function renderSheetDetails(c) {
  return renderTextPanel(c,'Personality & backstory','journal','personality',['personalityTraits','ideals','bonds','flaws'])+renderTextPanel(c,'Proficiencies & languages','book','proficiencies',['languages','armorProficiencies','weaponProficiencies','toolProficiencies']);
}
function editSheetText(title,keys) {
  const c=character();setModal(title,`<div class="form-grid">${keys.map(key=>textarea(SHEET_TEXT[key],key,c[key],3)).join('')}</div>${actions()}`,data=>{for(const key of keys)c[key]=textValue(data,key);modal.close();commit('Character sheet updated.');});
}
function editEssentials() {
  const c=character();setModal('Keep your eyes open.',`<div class="form-grid">${textarea(SHEET_TEXT.senses,'senses',c.senses,4)}${field('Passive Perception bonus','passivePerceptionBonus',c.passivePerceptionBonus,'number','required min="-99" max="99" step="1" data-full')}</div><p class="form-help">Passive Perception = 10 + Perception skill bonus + this adjustment. Current total: ${passivePerception(c)}. Record superior darkvision and other senses above.</p>${actions()}`,data=>{c.senses=textValue(data,'senses');c.passivePerceptionBonus=num(data,'passivePerceptionBonus');modal.close();commit('Senses updated.');});
}
function renderCombat(c) {
  return `<div class="combat-grid" data-sheet-group><div class="hp-block" ${sheetEntry('hp','Hit points')}><div class="tiny-label hp-title">${icon('heart')}HIT POINTS${c.tempHp?` <span>+${c.tempHp} TEMP</span>`:''}</div><div class="hp-numbers"><strong>${c.hp}</strong><span>/ ${c.maxHp}</span></div><div class="hp-track${c.hp/c.maxHp<.3?' low':''}"><div style="width:${c.hp/c.maxHp*100}%"></div></div><div class="hp-tools">${btn('hp',icon('minus')+'Harm','','data-kind="damage"')}${btn('hp',icon('plus')+'Heal','','data-kind="heal"')}</div></div><div class="combat-stat" ${sheetEntry('ac','Armor class')}><span class="tiny-label">ARMOR CLASS</span>${icon('shield')}<strong>${c.ac}</strong><small>AC</small></div>${btn('initiative',`<span class="tiny-label">INITIATIVE</span>${icon('bolt')}<strong>${signed(initiative(c))}</strong><small>Tap to roll</small>`,'combat-stat',sheetEntry('initiative','Initiative'))}<div class="combat-stat" ${sheetEntry('speed','Speed')}><span class="tiny-label">SPEED</span>${icon('boot')}<strong>${walkingSpeed(c)}<span style="font-size:10px"> ft.</span></strong><small>Walking</small></div></div><div class="status-row" data-sheet-group>${btn('conditions',icon(c.conditions.length||c.exhaustion?'flag':'check')+esc([...c.conditions,...(c.exhaustion?['Exhaustion '+c.exhaustion]:[])].join(', ')||'Feeling good. No conditions.'),'condition-summary',sheetEntry('conditions','Conditions'))}${btn('inspiration',icon('star')+'Heroic Inspiration'+(c.inspiration?' · ready':''),`inspiration${c.inspiration?' active':''}`,`${sheetEntry('inspiration','Heroic Inspiration')} aria-pressed="${c.inspiration}" title="Spend Heroic Inspiration to reroll one die immediately after rolling it; use the new roll. Track the reroll manually."`)}</div>${c.defenses?`<div class="combat-notes" ${sheetEntry('defenses',SHEET_TEXT.defenses)}><span>${esc(c.defenses)}</span></div>`:''}${c.hp===0?`<div class="death-saves" ${sheetEntry('death-saves','Death saving throws')}><div class="death-counter">Success ${Array.from({length:3},(_,i)=>btn('death-counter','',i<c.deathSuccess?'active':'',`data-kind="success" data-value="${i<c.deathSuccess?i:i+1}" aria-label="Set ${i+1} death save successes"`)).join('')}</div><div class="death-counter">Failure ${Array.from({length:3},(_,i)=>btn('death-counter','',i<c.deathFailure?'active':'',`data-kind="failure" data-value="${i<c.deathFailure?i:i+1}" aria-label="Set ${i+1} death save failures"`)).join('')}</div>${btn('death-roll',icon('dice')+'Death save','btn btn-sm',`${c.deathSuccess>=3||c.deathFailure>=3?'disabled':''}`)}${c.deathSuccess>=3||c.deathFailure>=3?`<div class="death-message">${c.deathFailure>=3?'Three failures. Check with your DM.':'Stable. You’re still at 0 HP.'}</div>`:''}</div>`:''}`;
}
function renderAttack(c,a) {const hit=attackBonus(c,a);return `<div class="action-row" ${sheetEntry(a.id,a.name)}><div class="item-symbol">${itemIconMarkup({name:a.name,category:'Weapon'},a.name.toLowerCase().includes('bow')?'bow':'sword')}</div><div class="action-info">${btn('attack',esc(a.name),'',`data-id="${a.id}" style="padding:0;text-align:left;font-size:11px;font-weight:600;margin-bottom:5px" aria-label="Edit ${esc(a.name)}"`)}<small style="display:block">${esc(a.type)}${a.range?' · '+esc(a.range):''}${a.rollMode!=='normal'?' · '+esc(a.rollMode):''}</small>${a.notes?`<small class="attack-notes">${esc(a.notes)}</small>`:''}</div><div class="action-rolls">${btn('attack-roll',icon('dice')+signed(hit),'roll-button',`data-id="${a.id}" aria-label="Roll ${esc(a.name)} to hit"`)}${btn('damage-roll',esc(a.damage),'roll-button damage-button',`data-id="${a.id}" aria-label="Roll ${esc(a.name)} damage"`)}</div></div>`;}
function renderJournalPeek(c) {
  const preview=c.notes.find(n=>n.pinned)||c.notes[0];
  const notes=c.notes.filter(n=>n===preview||isSheetFavorite(c,'journal',n.id));
  return `<section class="panel" data-sheet-section="journal"><div class="panel-heading"><h2>${icon('journal')}Adventure journal</h2>${btn('note',icon('plus'),'icon-btn','aria-label="Write a note"')}</div>${notes.length?notes.map(n=>`<div class="journal-preview" ${sheetEntry(n.id,n.title)}><div class="note-preview-tag">${icon('pin')}${esc(n.tag||'Note')} / ${esc(c.campaign)}</div><h3 class="note-preview-title">${esc(n.title)}</h3><div class="note-preview-text">${esc(n.body)}</div><div class="note-preview-footer"><small>${c.notes.length} notes in your journal</small>${btn('navigate','Open journal '+icon('arrow'),'text-btn','data-route="journal"')}</div></div>`).join(''):empty('journal','Every quest has a story','Jot down a clue, a name, or your next big idea.','note','Write a note')}</section>`;
}
function renderPackPeek(c) {
  const sorted=[...c.items].sort((a,b)=>(a.category==='Consumable'?-1:0)-(b.category==='Consumable'?-1:0));
  const items=sorted.filter((i,index)=>index<3||isSheetFavorite(c,'pack',i.id));
  return `<section class="panel pack-preview" data-sheet-section="pack"><div class="panel-heading"><h2>${icon('bag')}In your pack</h2>${btn('navigate','View all '+icon('arrow'),'text-btn','data-route="inventory"')}</div>${items.length?items.map(i=>`<div class="action-row" ${sheetEntry(i.id,i.name)}><div class="item-symbol${i.category==='Consumable'?' potion':''}">${itemIconMarkup(i)}</div><div class="action-info"><strong>${esc(i.name)}</strong><small>${esc(i.category)}${i.equipped?' · Equipped':''}</small></div><span class="qty">×${i.qty}</span></div>`).join(''):`<div class="panel-body" data-sheet-extra style="font-size:11px;color:var(--muted)">Your pack is ready for its first treasure.</div>`}<div class="coin-footer" ${sheetEntry('coins','Coin purse')}><span class="coin-purse-title">Coin purse</span>${btn('currency','Manage '+icon('chevron'),'text-btn','aria-label="Edit coin purse"')}${renderCoinBalances(c)}</div></section>`;
}

function searchToolbar(placeholder,action='',label='') {return `<div class="toolbar"><label class="search-field">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(query)}"></label>${action?btn(action,icon('plus')+label,'btn btn-primary'):''}</div>`;}
function renderInventory() {
  const c=character(),weight=c.items.reduce((n,i)=>n+i.weight*i.qty,0),items=c.items.filter(i=>(filter==='All'||filter==='Equipped'&&i.equipped||i.category===filter)&&(i.name+' '+i.description).toLowerCase().includes(query.toLowerCase()));
  return pageHeading('Inventory',btn('item',icon('plus')+'Add item','btn btn-primary'))+
    `<div class="summary-grid inventory-summary"><div class="summary-card">${icon('bag')}<div><strong>${c.items.reduce((n,i)=>n+i.qty,0)}</strong><small>Items carried</small></div></div><div class="summary-card">${icon('boot')}<div><strong>${weight.toLocaleString(undefined,{maximumFractionDigits:1})} <span style="font-size:12px">lb.</span></strong><small>Capacity ${c.stats.str*15} lb. ${weight>c.stats.str*15?'· Over capacity':''}</small></div></div><div class="summary-card currency-summary"><div class="coin-purse-heading"><span class="coin-purse-title">Coin purse</span>${btn('currency','Manage '+icon('chevron'),'text-btn','aria-label="Edit coin purse"')}</div>${renderCoinBalances(c)}</div></div>`+
    searchToolbar('Search your inventory…')+`<div class="filter-tabs">${['All','Equipped','Weapon','Armor','Gear','Consumable','Treasure'].map(f=>btn('filter',f,`filter-tab${filter===f?' active':''}`,`data-filter="${f}" aria-pressed="${filter===f}"`)).join('')}</div><div class="panel inventory-list">${items.length?items.map(i=>`<div class="action-row"><div class="item-symbol">${itemIconMarkup(i)}</div><div class="action-info"><strong>${esc(i.name)}</strong><div class="inventory-details"><span class="badge">${i.category}</span><small>${i.weight} lb. each</small>${i.wiki?ext(referenceURL(i.wiki,i.name,'equipment'),'Rules '+icon('external'),'text-btn'):''}</div>${i.description?`<p class="inventory-stats">${esc(i.description)}</p>`:''}</div><div class="item-right"><div class="quantity-stepper">${btn('quantity',icon('minus'),'',`data-id="${i.id}" data-delta="-1" aria-label="Remove one ${esc(i.name)}" ${i.qty===0?'disabled':''}`)}<span>${i.qty}</span>${btn('quantity',icon('plus'),'',`data-id="${i.id}" data-delta="1" aria-label="Add one ${esc(i.name)}" ${i.qty>=99999?'disabled':''}`)}</div>${btn('equip',icon(i.equipped?'check':'plus')+(i.equipped?'Equipped':'Equip'),`equipped-btn${i.equipped?' active':''}`,`data-id="${i.id}" aria-pressed="${i.equipped}"`)}${i.category==='Consumable'?btn('use-item','Use','btn btn-sm',`data-id="${i.id}" ${i.qty===0?'disabled':''}`):''}${btn('item',icon('edit'),'icon-btn',`data-id="${i.id}" aria-label="Edit ${esc(i.name)}"`)}</div></div>`).join(''):empty('bag',query?'No treasures found':'Travel light. Dream big.',query?'Try a different search or inventory filter.':'Add equipment, potions, and the curious things you find along the way.','item','Add item')}</div><p class="data-caption">Weight includes item quantities. Equipping gear marks it on the sheet; update armor class and attacks to match your equipment. Standard carrying capacity is Strength × 15.</p>`;
}
function renderJournal() {
  const c=character(),notes=[...c.notes].filter(n=>(filter==='All'||filter==='Pinned'&&n.pinned||n.tag===filter)&&(n.title+' '+n.body).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||Date.parse(b.updated)-Date.parse(a.updated));
  return pageHeading('Adventure Journal',btn('note',icon('plus')+'Write a note','btn btn-primary'))+searchToolbar('Search your notes…')+`<div class="filter-tabs">${['All','Pinned','Session','Quest','People','Lore','Personal'].map(f=>btn('filter',f,`filter-tab${filter===f?' active':''}`,`data-filter="${f}" aria-pressed="${filter===f}"`)).join('')}</div><div class="notes-grid">${notes.length?notes.map(n=>`<article class="note-card${n.pinned?' pinned':''}"><div class="note-card-head"><span class="badge">${esc(n.tag||'Note')}</span>${btn('pin-note',icon('pin'),`icon-btn${n.pinned?' pin-active':''}`,`data-id="${n.id}" aria-label="${n.pinned?'Unpin':'Pin'} ${esc(n.title)}" aria-pressed="${n.pinned}"`)}</div><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p><div class="note-card-footer"><time datetime="${esc(n.updated)}">${new Date(n.updated).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</time><div>${btn('view-note','Read '+icon('arrow'),'text-btn',`data-id="${n.id}"`)}</div></div></article>`).join(''):empty('journal',query?'No notes found':'The page is yours.',query?'Try another phrase or a different category.':'Record your first session, a character secret, or a lead you can’t let go.','note','Write a note')}</div>`;
}
function renderSpells() {
  const c=character(),ability=castingAbility(c),spells=c.spells.filter(s=>(filter==='All'||filter==='Ready'&&s.prepared||filter==='Cantrips'&&s.level===0||filter==='Concentration'&&s.concentration)&&(s.name+' '+s.school).toLowerCase().includes(query.toLowerCase()));
  return pageHeading('Spellbook',btn('spell',icon('plus')+'Add spell','btn btn-primary'))+
  `<div class="summary-grid"><div class="summary-card">${icon('spark')}<div><strong>${8+proficiency(c.level)+mod(c.stats[ability])}</strong><small>Spell save DC · ${ability.toUpperCase()}</small></div></div><div class="summary-card">${icon('bolt')}<div><strong>${signed(proficiency(c.level)+abilityCheckBonus(c,ability))}</strong><small>Spell attack bonus</small></div></div><div class="summary-card">${icon('book')}<div><strong>${c.spells.filter(s=>s.prepared).length}</strong><small>Prepared spells</small></div></div></div>`+
  `<section class="panel slot-panel"><strong>Spell slots</strong>${c.slots.some(s=>s.max)?c.slots.map((s,i)=>s.max?`<div class="slot-level">Level ${i+1}${slotDots(s,i)}</div>`:'').join(''):'<span style="font-size:11px;color:var(--muted)">Set your available spell slots.</span>'}${btn('slots','Edit slots','btn btn-sm')}</section>${c.concentration?`<div class="concentration-banner">${icon('spark')}Concentrating on <strong>${esc(c.concentration)}</strong>${btn('end-concentration',icon('close'),'icon-btn','aria-label="End concentration"')}</div>`:''}`+
  searchToolbar('Find a spell…')+`<div class="filter-tabs">${['All','Ready','Cantrips','Concentration'].map(f=>btn('filter',f,`filter-tab${filter===f?' active':''}`,`data-filter="${f}" aria-pressed="${filter===f}"`)).join('')}</div><div class="spell-grid">${spells.length?spells.map(s=>`<article class="spell-card"><div class="spell-card-head"><div class="item-symbol">${icon('spark')}</div><div class="action-info"><h2>${ext(referenceURL(s.wiki,s.name,'spell'),esc(s.name)+' '+icon('external'))}</h2><small>${s.level===0?'Cantrip':`Level ${s.level}`} · ${esc(s.school)}${s.concentration?' · Concentration':''}</small></div>${btn('spell',icon('edit'),'icon-btn',`data-id="${s.id}" aria-label="Edit ${esc(s.name)}"`)}</div><dl><div><dt>Casting time</dt><dd>${esc(s.castingTime)||'—'}</dd></div><div><dt>Range</dt><dd>${esc(s.range)||'—'}</dd></div><div><dt>Duration</dt><dd>${esc(s.duration)||'—'}</dd></div><div><dt>Availability</dt><dd>${s.prepared?'Prepared':'Not readied'}</dd></div></dl>${s.notes?`<p>${esc(s.notes)}</p>`:''}<div class="spell-card-foot">${btn('prepare',icon(s.prepared?'check':'plus')+(s.prepared?'Readied':'Ready spell'),`equipped-btn${s.prepared?' active':''}`,`data-id="${s.id}" aria-pressed="${s.prepared}"`)}${btn('cast',icon('spark')+'Cast spell','btn btn-primary btn-sm',`data-id="${s.id}"`)}</div></article>`).join(''):empty('book',query?'No spells found':'Begin your spellbook.',query?'Try a different search or spell filter.':'Add the spells your character knows. Each one can link to the official 2024 spell reference.','spell','Add spell')}</div><p class="data-caption">Slots are tracked manually so this works with your table’s class and multiclass rules. Warlocks can restore pact slots manually after a short rest. Readying a spell is a tracking aid, without enforcing class limits.</p>`;
}
function renderDice() {return pageHeading('Dice Roller')+`<div class="dice-layout"><section class="dice-tray"><p class="tray-eyebrow">A LITTLE ROLL OF DESTINY</p><div class="big-die" id="tray-die">${icon('dice')}<strong>${lastRoll?lastRoll.total:'20'}</strong></div><div class="dice-selection">${[4,6,8,10,12,20,100].map(d=>btn('select-die',icon('dice')+`d${d}`,`dice-select${diceExpression===`1d${d}`?' active':''}`,`data-sides="${d}"`)).join('')}</div><form id="dice-form" class="dice-form"><input id="dice-expression" name="expression" value="${esc(diceExpression)}" aria-label="Dice expression, for example 2d6 plus 3" maxlength="30" autocomplete="off" spellcheck="false"><button type="submit" class="btn btn-primary">${icon('dice')}Roll dice</button></form><div class="dice-modes">${['normal','advantage','disadvantage'].map(m=>btn('roll-mode',m[0].toUpperCase()+m.slice(1),`dice-mode${rollMode===m?' active':''}`,`data-mode="${m}" aria-pressed="${rollMode===m}"`)).join('')}</div><p class="roll-detail" id="roll-detail" aria-live="polite">${lastRoll?esc(rollBreakdown(lastRoll)):'Try 1d20+4, 2d6, or 4d6. The dice await.'}</p><p class="data-caption">Advantage & disadvantage apply to a single d20.</p></section><section class="panel"><div class="panel-heading"><h2>${icon('journal')}This session’s rolls</h2>${btn('clear-rolls','Clear','text-btn')}</div><div class="roll-history">${rollHistory.length?rollHistory.map(r=>`<div class="history-row"><div class="history-result">${r.total}</div><div><strong>${esc(r.label)}</strong><small>${esc(r.expression)}${r.mode!=='normal'?' · '+r.mode:''}${r.natural===20?' · Natural 20!':''}${r.natural===1?' · Natural 1':''}</small></div><time>${new Date(r.time).toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'})}</time></div>`).join(''):empty('dice','A clean slate.','Your rolls appear here during this visit. What will your first one be?')}</div></section></div>`;}
const wikiEntries=[['Classes','2024 progression & features.','people','classes'],['Spells','Revised spell descriptions.','spark','spells'],['Weapons','Properties & Weapon Mastery.','sword','weapons'],['Armor','Armor training & equipment.','shield','armor'],['Adventuring gear','Potions, tools, and supplies.','bag','adventuring-gear'],['Magic items','Current item rules.','star','wondrous-items'],['Backgrounds','Ability increases & Origin feats.','journal','backgrounds'],['Feats','Origin, General, and more.','bolt','feats'],['Species','Your character’s heritage.','leaf','species'],['Rules glossary','Conditions, rests, and actions.','compass','rules']];
function renderWiki() {
  const c=character();
  const books=[['Player’s Handbook (2024)','Character options & player rules.','book','phb-2024'],['Dungeon Master’s Guide (2024)','DM guidance & magic items.','compass','dmg-2024'],['Monster Manual (2025)','Monsters for the revised core rules.','people','mm-2024']];
  return pageHeading('2024 Compendium')+catalogBrowser()+`<div class="adventure-tip">${icon('compass')}<div><strong>2024 core rules.</strong>These references use the revised rules on D&D Beyond. Basic Rules are free; full rulebooks may require account access. Links open in a new tab and need an internet connection.</div></div><h2 class="wiki-section">Explore the 2024 Basic Rules</h2><div class="wiki-grid">${wikiEntries.map(([name,desc,sym,key])=>ext(wikiURL(key),icon(sym)+`<div><strong>${name}</strong><small>${desc}</small></div>`+icon('external'),'wiki-card')).join('')}</div><h2 class="wiki-section">Your core rulebooks</h2><div class="wiki-grid">${books.map(([name,desc,sym,path])=>ext('https://www.dndbeyond.com/sources/dnd/'+path,icon(sym)+`<div><strong>${name}</strong><small>${desc}</small></div>`+icon('external'),'wiki-card')).join('')}</div><h2 class="wiki-section">For ${esc(c.name)}</h2><div class="wiki-grid">${ext(wikiURL(c.class),icon('people')+`<div><strong>${esc(c.class)}</strong><small>2024 class progression & features</small></div>`+icon('external'),'wiki-card')}${c.spells.slice(0,5).map(s=>ext(referenceURL(s.wiki,s.name,'spell'),icon('spark')+`<div><strong>${esc(s.name)}</strong><small>Spell rules & descriptions</small></div>`+icon('external'),'wiki-card')).join('')}</div>`;
}
function renderSettings() {return pageHeading('Settings & Backup')+`<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>${icon('settings')}Your preferences</h2></div><div class="setting-row">${icon('sound')}<div><strong>8-bit sound effects</strong><p>A little fanfare for dice rolls and new levels.</p></div>${btn('sound','','toggle-switch'+(state.settings.sound?' active':''),`role="switch" aria-checked="${state.settings.sound}" aria-label="8-bit sound effects"`)}</div><div class="setting-row">${icon('people')}<div><strong>Your adventurers</strong><p>${state.characters.length} character${state.characters.length!==1?'s':''} saved in this browser.</p></div>${btn('characters','Manage','btn btn-sm')}</div><div class="setting-row">${icon('scan')}<div><strong>Scan a paper sheet</strong><p>Turn handwritten or printed sheet photos into a character. Review before saving.</p></div>${btn('scan-sheet','Scan a sheet','btn btn-sm')}</div><div class="setting-row">${icon('people')}<div><strong>The default party</strong><p>Add Melchior, Balin, and Teyla with 2024 class rules and their chosen origins.</p></div>${btn('default-party','Add default party','btn btn-sm')}</div><div class="setting-row">${icon('book')}<div><strong>Try the 2024 example</strong><p>Add the updated Ranger alongside your saved characters.</p></div>${btn('demo-2024','Add 2024 example','btn btn-sm')}</div><div class="setting-row">${icon('compass')}<div><strong>Take Questlog with you</strong><p>Install on your home screen for easy access.</p></div>${btn('install','How to','btn btn-sm')}</div></section><section class="panel"><div class="panel-heading"><h2>${icon('shield')}Keep your adventures safe</h2></div><div class="setting-row">${icon('download')}<div><strong>Export a backup</strong><p>All characters, notes, items, and spells in one JSON file.</p></div>${btn('export','Export','btn btn-sm')}</div><div class="setting-row">${icon('upload')}<div><strong>Import a backup</strong><p>Add characters from a version ${SAVE_VERSION} Questlog file. Older backups are not supported.</p></div>${btn('import','Import','btn btn-sm')}</div><div class="panel-body about-copy"><p>Your data lives in this browser on this device. Private browsing, clearing site data, or changing the website address can remove access to it. Export a backup regularly. Use export and import to move to another phone or computer. This release starts a new save format; previous browser saves are not loaded and older backups cannot be imported.</p>${storageBlocked?btn('recover-storage','Enable saving for this sheet','btn btn-danger'):''}</div></section><section class="panel"><div class="panel-heading"><h2>${icon('heart')}Made for the table</h2><span class="badge">2024 RULES</span></div><div class="panel-body about-copy"><p>Questlog is an independent fan-made 5e character tracker with a soft spot for old-school adventures. It’s a companion for your table: keep your DM’s rulings, class choices, and house rules close.</p><p>The demo and rest defaults follow the 2024 core rules. Long Rests restore all Hit Dice and normally remove one Exhaustion level. Exhaustion adjusts sheet D20 Tests and walking speed; other conditions remain reminders. Class choices, spell effects, Heroic Inspiration rerolls, and Weapon Mastery effects are player-managed. The default party uses 2024 classes while retaining the group’s older origin choices and Beast subclass. Teyla is a Wood Elf Folk Hero. Review the pinned conversion notes for adjustments and table rulings.</p><p>Default references open ${ext(RULES_URL,'the official 2024 Basic Rules')}. Custom reference links are kept. Full core book links are in the 2024 compendium and may require D&D Beyond access. Portraits are made with ${ext('https://github.com/Maxichance/bricktrait','Bricktrait by Maxichance')} (MIT), using LDraw parts (CC BY). Tap your portrait to make it your own. Original pixel scenery is included with the app. Character tracking needs no account or server. Photo scanning needs an online scan service.</p><p>Rules adapted from SRD 5.2.1: ${ext('https://www.dndbeyond.com/srd','Wizards of the Coast')} · ${ext('https://creativecommons.org/licenses/by/4.0/','CC BY 4.0')}. See the project README for attribution.</p></div></section><section class="panel"><div class="panel-heading"><h2>${icon('leaf')}Offline, and ready for the road</h2></div><div class="panel-body about-copy"><p>Open Questlog once while online to cache the app. Your sheet, notes, inventory, and dice then work without an internet connection. Reference pages, photo scanning, and portrait parts you have not opened yet need a connection. Saved portraits work offline.</p><p>On iPhone, use Safari → Share → Add to Home Screen. On Android, use your browser’s Install app or Add to Home screen option.</p><p>For GitHub Pages setup, follow the README included in the project.</p></div></section></div>`;}

// Dialogs keep the on-sheet flows small enough for a thumb and a dice bag.
function showCharacters() {const c=character();setModal('Choose your adventurer.',`<p class="modal-intro">Different stories. One little journal.</p>${state.characters.map(x=>btn('switch-character',`<span class="mini-avatar">${portraitMarkup(x)}</span><div><strong>${esc(x.name)}</strong><small>Level ${x.level} ${esc(x.race)} ${esc(x.class)}</small></div>${icon(x.id===c.id?'check':'chevron')}`,`character-option${x.id===c.id?' active':''}`,`data-id="${x.id}"`)).join('')}<div class="modal-actions">${btn('new-character',icon('plus')+'New character','btn btn-primary')}${btn('scan-sheet',icon('scan')+'Scan a sheet','btn')}${btn('export',icon('download')+'Backup','btn')}</div>`);}
function editPortrait() {
  if(modal.open){$('#modal-form').requestSubmit();if(modal.open)return;}
  const c=character(),id=c.id;
  openPortraitMaker({character:c,onSave:portrait=>{
    const target=state.characters.find(item=>item.id===id);
    if(!target)throw new Error('This character is no longer available. Close the editor and choose a character.');
    const next={...state,characters:state.characters.map(item=>item.id===id?{...item,portrait}:item)};
    if(new Blob([JSON.stringify(next)]).size>2000000)throw new Error('This portrait would exceed the 2 MB save limit. Export a backup and remove unused entries first.');
    target.portrait=portrait;commit('Portrait saved for '+target.name+'.');
  }});
}
function editCharacter(isNew=false) {
  const c=isNew?makeCharacter():character();
  setModal(isNew?'A new story begins.':'Meet your adventurer.',`<p class="modal-intro">${isNew?'Choose a name and a calling. Then customize your stats, equipment, and spells on your sheet.':'The little details make a character your own.'}</p><div class="form-grid">${field('Character name','name',isNew?'':c.name,'text','required maxlength="120" data-full placeholder="What shall we call you?"')}${field('Player name','playerName',c.playerName,'text','maxlength="120"')}${field('Level','level',c.level,'number','required min="1" max="20" step="1"')}${field('Experience points','xp',c.xp,'number','required min="0" max="100000000" step="1"')}${characterChoice('Species / race','race',c.race,{required:true})}${select('Class','class',Object.keys(CLASSES),c.class)}${classPreview(c.class)}${characterChoice('Subclass','subclass',c.subclass,{entries:SUBCLASSES.filter(option=>option.className===c.class)})}${characterChoice('Background','background',c.background)}${select('Alignment','alignment',['Lawful Good','Neutral Good','Chaotic Good','Lawful Neutral','True Neutral','Chaotic Neutral','Lawful Evil','Neutral Evil','Chaotic Evil','Unaligned'],c.alignment)}${field('Campaign','campaign',c.campaign,'text','maxlength="100"')}</div><p class="form-help">${isNew?'Class hit die, saving throws, armor and weapon training, and species speed and senses are filled in for a new character. HP starts at first level; set higher-level HP in Edit stats. Choose background ability increases, skill choices, feats, and features using the previews. Species traits and feats are recorded and applied manually.':'Dropdown previews show 2024 options; custom and earlier-book entries are supported. Changing an option doesn’t rebuild your existing stats, notes, or equipment. Edit hit die size, scores, spells, and features as needed. Set level and XP here when copying a sheet, or use Level up to gain HP as you advance.'}</p>${!isNew?btn('portrait',icon('edit')+'Make or edit portrait','btn portrait-details-action'):''}${actions(isNew?'Create character':'Save character',!isNew&&state.characters.length>1?btn('delete-character',icon('trash'),'btn btn-danger left-action','aria-label="Delete this character"'):'')}`,data=>{
    c.playerName=textValue(data,'playerName');c.level=num(data,'level');c.xp=num(data,'xp');c.hitDice=Math.min(c.hitDice,c.level);c.name=textValue(data,'name');c.race=textValue(data,'race');c.class=textValue(data,'class');c.subclass=textValue(data,'subclass');c.background=textValue(data,'background');c.alignment=textValue(data,'alignment');c.campaign=textValue(data,'campaign');
    if(isNew){c.hitDice=c.level;applyStartingOptions(c);state.characters.push(c);state.activeId=c.id;}
    modal.close();route='sheet';location.hash='sheet';commit(isNew?'Your story starts here. Welcome, '+c.name+'.':'Character updated.');
  });
}
function editAbilities() {const c=character();setModal('A few natural talents.',`<p class="modal-intro">Edit your total scores, including background increases, feats, and item bonuses. Modifiers and proficient checks update automatically.</p><div class="form-grid">${Object.entries(ABILITIES).map(([key,label])=>field(label,key,c.stats[key],'number','required min="1" max="30" step="1"')).join('')}</div><p class="form-help">Changing Constitution won’t recalculate maximum HP. Update it in your combat stats, including any retroactive hit point changes.</p>${actions()}`,data=>{for(const key of Object.keys(ABILITIES))c.stats[key]=num(data,key);modal.close();commit('Ability scores updated.');});}
function editCombat() {
  const c=character();
  setModal('Ready for the next encounter.',`<div class="form-grid">${field('Maximum hit points','maxHp',c.maxHp,'number','required min="1" max="9999" step="1"')}${field('Current hit points','hp',c.hp,'number','required min="0" max="9999" step="1"')}${field('Temporary hit points','tempHp',c.tempHp,'number','required min="0" max="9999" step="1"')}${field('Armor class (total, including shield)','ac',c.ac,'number','required min="0" max="99" step="1"')}${field('Base walking speed (before Exhaustion, ft.)','speed',c.speed,'number','required min="0" max="999" step="1"')}${field('Initiative bonus (in addition to Dexterity)','initiativeBonus',c.initiativeBonus,'number','required min="-99" max="99" step="1"')}${select('Hit die size','hitDie',['d6','d8','d10','d12'],'d'+c.hitDie)}${field('Hit dice remaining','hitDice',c.hitDice,'number',`required min="0" max="${c.level}" step="1"`)}${textarea(SHEET_TEXT.defenses,'defenses',c.defenses,3)}</div><label class="check-field"><input name="initiativeAdvantage" type="checkbox" ${c.initiativeAdvantage?'checked':''}>Advantage on initiative</label><p class="form-help">Enter your total armor class. Exhaustion reduces the displayed walking speed automatically. Record shield bonuses and other situational defenses in the notes.</p>${actions()}`,data=>{
    if(num(data,'hp')>num(data,'maxHp'))throw new Error('Current HP cannot exceed maximum HP.');
    c.initiativeAdvantage=data.has('initiativeAdvantage');
    for(const key of ['maxHp','hp','tempHp','ac','speed','hitDice','initiativeBonus'])c[key]=num(data,key);
    c.hitDie=Number(textValue(data,'hitDie').slice(1));c.defenses=textValue(data,'defenses');
    if(c.hp>0){c.deathSuccess=0;c.deathFailure=0;}
    modal.close();commit('Combat stats updated.');
  });
}

function showHP(kind='damage') {const c=character();setModal('A little battle damage?',`<div class="hp-modal-display">${c.hp} <small>/ ${c.maxHp} HP</small></div><div class="hp-modal-temp">${c.tempHp?c.tempHp+' temporary hit points':'No temporary hit points'}</div>${field('Amount','amount',1,'number','required min="0" max="9999" step="1" class="hp-input" autofocus')}<div class="hp-action-grid">${btn('hp-apply',icon('minus')+'Damage','btn btn-danger','data-kind="damage"')}${btn('hp-apply',icon('plus')+'Heal','btn btn-primary','data-kind="heal"')}${btn('hp-apply',icon('shield')+'Temp HP','btn','data-kind="temp"')}</div><p class="form-help">Damage uses temporary HP first. Temporary HP doesn’t stack; the higher value is kept. Check massive-damage and concentration rules with your DM.</p>`,data=>applyHP(data,kind));}
function applyHP(data,kind) {const c=character();const n=num(data,'amount');if(!Number.isInteger(n)||n<0||n>9999)throw new Error('Enter an amount from 0 to 9,999.');changeHP(c,n,kind);modal.close();commit(kind==='damage'?`${n} damage taken.`:kind==='heal'?`${n} healing applied.`:`Temporary HP is now ${c.tempHp}.`);}
function showConditions() {
  const c=character();
  setModal('How are you holding up?',`<p class="modal-intro">Track your current conditions. Tap again to clear one.</p><div class="condition-grid">${CONDITIONS.map(v=>btn('condition',esc(v)+(c.conditions.includes(v)?icon('check'):''),`condition-chip${c.conditions.includes(v)?' active':''}`,`data-condition="${v}" aria-pressed="${c.conditions.includes(v)}"`)).join('')}</div><div style="margin-top:18px">${field('Exhaustion level (2024: 0–6)','exhaustion',c.exhaustion,'number','required min="0" max="6" step="1"')}</div><p class="form-help">2024 Exhaustion subtracts 2 per level from all D20 Tests and 5 feet per level from Speed. At level 6, the character dies. Sheet checks, saves (including death saves), attacks, initiative, passive Perception, and walking speed include these penalties. Ability scores, damage, and spell save DC stay unchanged. Apply penalties manually to custom dice rolls; other conditions are reminders. ${ext(wikiURL('rules'),'Read the 2024 conditions '+icon('external'))}</p>${actions('Done')}`,data=>{c.exhaustion=num(data,'exhaustion');modal.close();commit(c.exhaustion===6?'Exhaustion 6: the character dies. Check with your DM.':'Condition tracker updated.');});
}
function showRest(kind='short') {
  const c=character();
  if(c.hp<1) {toast('You need at least 1 HP to start a rest.',true);return;}
  setModal(kind==='long'?'A well-earned night’s rest.':'Catch your breath.',`<div class="rest-illustration">${campArt()}</div><div class="choice-buttons">${btn('rest','Short rest',`btn${kind==='short'?' btn-primary':''}`,'data-kind="short"')}${btn('rest','Long rest',`btn${kind==='long'?' btn-primary':''}`,'data-kind="long"')}</div>${kind==='long'?`<ul class="rest-summary"><li>Restore ${c.maxHp-c.hp} HP and clear temporary HP.</li><li>Regain all ${c.level-c.hitDice} spent Hit Dice.</li><li>Restore all spell slots and rest-based resources.</li><li>End concentration and reset death saves.</li></ul><label class="check-field"><input name="reduceExhaustion" type="checkbox" checked>Remove one Exhaustion level (${c.exhaustion} → ${Math.max(0,c.exhaustion-1)})</label><p class="form-help">A Long Rest normally takes 8 hours and requires at least 1 HP at its start. Wait at least 16 hours after the previous Long Rest before starting another. Uncheck Exhaustion recovery if an effect prevents it, such as unresolved dehydration or malnutrition. Restore reduced ability scores and HP maximums, and record feature benefits such as Human Heroic Inspiration, manually. Finish only once your DM confirms the rest qualifies.</p>`:`<p class="modal-intro" style="margin-top:18px">A Short Rest takes at least 1 hour. Spend Hit Dice to recover HP. You have ${c.hitDice} d${c.hitDie} available, with a ${signed(mod(c.stats.con))} Constitution modifier per die. Short-rest resources refresh; long-rest resources regain any configured Short Rest uses.</p>${field('Hit dice to spend','dice',0,'number',`required min="0" max="${c.hitDice}" step="1"`)}<p class="form-help">Pact slots and other special recovery rules can be updated manually in your spellbook.</p>`}${actions(kind==='long'?'Finish long rest':'Finish short rest')}`,data=>{
    let message='Long rest complete. The road awaits.';
    if(kind==='long')longRest(c,{reduceExhaustion:data.has('reduceExhaustion')});
    else {const count=num(data,'dice'),heal=shortRest(c,count);message=`Short rest complete. ${count?`${count} Hit Dice restored ${heal} HP.`:'You saved your Hit Dice.'}`;}
    modal.close();commit(message);
  });
}
function showXP() {const c=character();setModal('A little experience goes a long way.',`<p class="modal-intro">Currently ${fmt(c.xp)} XP. ${c.level<20?`Level ${c.level+1} starts at ${fmt(XP[c.level+1])} XP.`:'You’re a level 20 legend.'} Level up whenever your DM gives the word.</p><div class="form-grid">${field('Experience to add','amount',100,'number','required min="0" max="10000000" step="1"')}${field('Or set total XP','total','','number','min="0" max="100000000" step="1" placeholder="Leave blank to add"')}</div>${actions('Update experience')}`,data=>{c.xp=data.get('total')!==''?num(data,'total'):Math.min(100000000,c.xp+num(data,'amount'));modal.close();commit('Experience updated. Keep that adventure going.');});}
function showLevelUp() {const c=character();if(c.level>=20)return;const gain=Math.max(1,c.hitDie/2+1+mod(c.stats.con));setModal('Your next chapter awaits.',`<div class="level-up-preview"><span class="level-number">${c.level}</span>${icon('arrow')}<span class="level-number new">${c.level+1}</span></div><p class="modal-intro">Milestone or experience, a new level is a reason to celebrate. Your proficiency bonus updates automatically.</p>${field('Hit points gained (including Constitution)','hpGain',gain,'number','required min="1" max="999" step="1"')}<p class="form-help">Suggested average: ${c.hitDie/2+1} + ${signed(mod(c.stats.con))} Constitution. You can roll a d${c.hitDie} and enter the total instead. Add class features, spell slots, spells, feats, and ability score improvements manually after leveling.</p>${actions('Let’s level up!')}`,data=>{levelUp(c,num(data,'hpGain'));persist();render();celebrate();});}
function celebrate() {const c=character();sound('level');const confetti=Array.from({length:30},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${-(i%9)*.23}s;animation-duration:${1.7+(i%5)*.2}s;background:${['#a9bf78','#d9c88b','#87a7a0','#cadc9b'][i%4]}"></i>`).join('');setModal('A new chapter unlocked.',`<div class="celebration"><div class="pixel-confetti">${confetti}</div><div class="avatar-frame">${portraitMarkup(c)}<span class="level-badge">LVL ${String(c.level).padStart(2,'0')}</span></div><h2>LEVEL UP!</h2><p>The road has changed you, ${esc(c.name.split(' ')[0])}.<br>And there’s still so much story left.</p><span class="badge">LEVEL ${c.level} ${esc(c.class).toUpperCase()} · ${c.maxHp} MAX HP</span><p>Check your class progression for new abilities, spells, and choices.</p>${ext(wikiURL(c.class),'View class progression '+icon('external'),'btn')}</div><div class="modal-actions">${btn('close','Onward, adventurer. '+icon('arrow'),'btn btn-primary')}</div>`);}

function editItem(id) {const c=character(),existing=c.items.find(i=>i.id===id),i=existing||{name:'',category:'Gear',qty:1,weight:0,equipped:false,description:'',wiki:''};setModal(existing?'A closer look at your gear.':'Something for your pack.',`${catalogPicker('item')}<div class="form-grid">${field('Item name','name',i.name,'text','required maxlength="200" data-full')}${select('Category','category',['Weapon','Armor','Gear','Consumable','Treasure'],i.category)}${field('Quantity','qty',i.qty,'number','required min="0" max="99999" step="1"')}${field('Weight each (lb.)','weight',i.weight,'number','required min="0" max="99999" step="0.01"')}${field('Reference link (optional)','wiki',i.wiki,'url','maxlength="2000" placeholder="https://www.dndbeyond.com/…"')}${textarea('Description / item notes','description',i.description,4)}</div><label class="check-field"><input type="checkbox" name="equipped" ${i.equipped?'checked':''}>Equipped</label><p class="form-help">A Potion of Healing takes a Bonus Action to drink or administer within 5 feet. Using one here rolls 2d4 + 2 and heals this character. Other consumables reduce their quantity only.</p>${actions(existing?'Save item':'Add to pack',existing?btn('delete-entry',icon('trash'),'btn btn-danger left-action',`data-type="items" data-id="${id}" aria-label="Delete item"`):'')}`,data=>{
    const item={id:existing?.id||uid(),name:textValue(data,'name'),category:textValue(data,'category'),qty:num(data,'qty'),weight:num(data,'weight'),description:textValue(data,'description'),wiki:textValue(data,'wiki'),equipped:data.has('equipped')};if(existing)Object.assign(existing,item);else c.items.push(item);modal.close();commit(existing?'Item updated.':'A new addition to your pack.');
  });}
function editCurrency() {const c=character();setModal('A little treasure to your name.',`<p class="modal-intro">Track every coin from your paper sheet.</p><div class="form-grid">${Object.entries(COINS).map(([key,unit])=>field(`<span class="coin-field-label">${coinStud(key)}${coinName(key)} pieces (${unit.toUpperCase()})</span>`,key,c[key],'number','required min="0" max="100000000" step="1"')).join('')}</div>${actions('Update purse')}`,data=>{Object.keys(COINS).forEach(k=>c[k]=num(data,k));modal.close();commit('Coin purse updated.');});}

function editNote(id) {const c=character(),existing=c.notes.find(n=>n.id===id),n=existing||{title:'',body:'',tag:'Session',pinned:false};setModal(existing?'Back to the story.':'A page for your next adventure.',`<div class="form-grid">${field('Note title','title',n.title,'text','required maxlength="200" data-full placeholder="A name, a clue, a questionable plan…"')}${select('Category','tag',['Session','Quest','People','Lore','Personal'],n.tag)}${textarea('Your notes','body',n.body,10,100000)}</div><label class="check-field"><input name="pinned" type="checkbox" ${n.pinned?'checked':''}>Pin this note to your character sheet</label>${actions('Save note',existing?btn('delete-entry',icon('trash'),'btn btn-danger left-action',`data-type="notes" data-id="${id}" aria-label="Delete note"`):'')}`,data=>{const note={id:existing?.id||uid(),title:textValue(data,'title'),body:String(data.get('body')||''),tag:textValue(data,'tag'),pinned:data.has('pinned'),updated:new Date().toISOString()};if(existing)Object.assign(existing,note);else c.notes.unshift(note);modal.close();commit('A little piece of the story, saved.');});}
function viewNote(id) {const n=character().notes.find(n=>n.id===id);if(!n)return;setModal(esc(n.title),`<div class="note-preview-tag">${esc(n.tag)} · ${new Date(n.updated).toLocaleDateString()}</div><div class="detail-paragraph">${esc(n.body)}</div><div class="modal-actions">${btn('close','Close','btn')}${btn('note',icon('edit')+'Edit note','btn btn-primary',`data-id="${n.id}"`)}</div>`);}
function editAttack(id) {const c=character(),existing=c.attacks.find(a=>a.id===id),a=existing||{name:'',ability:'str',bonus:0,proficient:true,damage:'1d6',type:'Slashing',range:'5 ft.',notes:'',rollMode:'normal'};setModal(existing?'Fine-tune your attack.':'Your next move.',`${catalogPicker('attack')}<div class="form-grid">${field('Attack name','name',a.name,'text','required maxlength="200" data-full')}${select('Attack ability','ability',Object.keys(ABILITIES),a.ability)}${select('Attack roll mode','rollMode',['normal','advantage','disadvantage'],a.rollMode)}${field('Additional attack bonus','bonus',a.bonus,'number','required min="-99" max="99" step="1"')}${field('Damage dice or fixed amount (include modifier)','damage',a.damage,'text','required maxlength="30" placeholder="1d8+4"')}${field('Damage type','type',a.type,'text','maxlength="100"')}${field('Range / reach','range',a.range,'text','maxlength="100"')}${textarea('Attack notes / alternate damage','notes',a.notes,3)}</div><label class="check-field"><input name="proficient" type="checkbox" ${a.proficient?'checked':''}>Add proficiency bonus to hit</label><p class="form-help">Attack bonuses use your current ability score and proficiency. Damage uses the shown formula or fixed amount; update it when your modifier changes. Presets suggest proficiency and Heavy disadvantage from your sheet; check special training and features. Record Weapon Mastery in attack notes. Light extra attacks and special attacks can have their own formulas. Exhaustion reduces attack rolls automatically, but leaves damage unchanged.</p>${actions('Save attack',existing?btn('delete-entry',icon('trash'),'btn btn-danger left-action',`data-type="attacks" data-id="${id}" aria-label="Delete attack"`):'')}`,data=>{const damage=textValue(data,'damage');rollDice(damage);const attack={id:existing?.id||uid(),name:textValue(data,'name'),ability:textValue(data,'ability'),bonus:num(data,'bonus'),proficient:data.has('proficient'),rollMode:textValue(data,'rollMode'),damage,type:textValue(data,'type'),range:textValue(data,'range'),notes:textValue(data,'notes')};if(existing)Object.assign(existing,attack);else c.attacks.push(attack);modal.close();commit('Attack ready.');});}
function editFeature(id) {
  const c=character(),existing=c.features.find(f=>f.id===id),f=existing||{name:'',description:'',maxUses:0,used:0,reset:'long',wiki:'',rollFormula:'',shortRestRecovery:0};
  setModal(existing?'A special talent.':'What makes you extraordinary?',`${catalogPicker('feat',c)}<div class="form-grid">${field('Feature / resource name','name',f.name,'text','required maxlength="200" data-full')}${field('Maximum uses / points (0 = unlimited)','maxUses',f.maxUses,'number','required min="0" max="999" step="1"')}${select('Refresh after','reset',['short','long','manual'],f.reset)}${field('Uses regained on Short Rest (long-rest resources)','shortRestRecovery',f.shortRestRecovery,'number','required min="0" max="999" step="1"')}${field('Uses already spent','used',f.used,'number','required min="0" max="999" step="1"')}${field('Dice formula (optional)','rollFormula',f.rollFormula,'text','maxlength="30" placeholder="1d8 or 1d10+3"')}${field('Reference link (optional)','wiki',f.wiki,'url','maxlength="2000"')}${textarea('What it does / your notes','description',f.description)}</div><p class="form-help">For superiority dice, enter 4 uses and 1d8. For 2024 Second Wind at Fighter level 3, enter 2 uses, long-rest refresh, 1 use regained on Short Rest, and 1d10+3. Rolling spends one use; apply healing or damage separately.</p>${actions('Save feature',existing?btn('delete-entry',icon('trash'),'btn btn-danger left-action',`data-type="features" data-id="${id}" aria-label="Delete feature"`):'')}`,data=>{
    const rollFormula=textValue(data,'rollFormula');if(rollFormula&&!validDiceFormula(rollFormula))throw new Error('Use a dice formula like 1d8 or 1d10+3.');
    if(num(data,'used')>num(data,'maxUses'))throw new Error('Used points cannot exceed maximum uses.');
    if(num(data,'shortRestRecovery')>num(data,'maxUses'))throw new Error('Short Rest recovery cannot exceed maximum uses.');
    const feature={id:existing?.id||uid(),shortRestRecovery:num(data,'shortRestRecovery'),name:textValue(data,'name'),description:textValue(data,'description'),maxUses:num(data,'maxUses'),used:num(data,'used'),reset:textValue(data,'reset'),wiki:textValue(data,'wiki'),rollFormula};
    if(existing)Object.assign(existing,feature);else c.features.push(feature);modal.close();commit('Feature saved.');
  });
}

function editSpell(id) {const c=character(),existing=c.spells.find(s=>s.id===id),s=existing||{name:'',level:1,school:'Evocation',castingTime:'1 action',range:'',duration:'Instantaneous',concentration:false,prepared:true,notes:'',wiki:''};setModal(existing?'A little spellcraft.':'A new spark of magic.',`<div class="form-grid">${field('Spell name','name',s.name,'text','required maxlength="200" data-full')}${field('Spell level (0 = cantrip)','level',s.level,'number','required min="0" max="9" step="1"')}${select('School','school',['Abjuration','Conjuration','Divination','Enchantment','Evocation','Illusion','Necromancy','Transmutation','Other'],s.school)}${field('Casting time','castingTime',s.castingTime,'text','maxlength="100"')}${field('Range','range',s.range,'text','maxlength="100"')}${field('Duration','duration',s.duration,'text','maxlength="100"')}${field('2024 reference link (blank = official spell reference)','wiki',s.wiki,'url','maxlength="2000"')}${textarea('Spell notes','notes',s.notes,4)}</div><label class="check-field"><input name="concentration" type="checkbox" ${s.concentration?'checked':''}>Requires concentration</label><label class="check-field"><input name="prepared" type="checkbox" ${s.prepared?'checked':''}>Prepared and ready to cast</label>${actions('Save spell',existing?btn('delete-entry',icon('trash'),'btn btn-danger left-action',`data-type="spells" data-id="${id}" aria-label="Delete spell"`):'')}`,data=>{const name=textValue(data,'name'),spell={id:existing?.id||uid(),name,level:num(data,'level'),school:textValue(data,'school'),castingTime:textValue(data,'castingTime'),range:textValue(data,'range'),duration:textValue(data,'duration'),concentration:data.has('concentration'),prepared:data.has('prepared'),notes:textValue(data,'notes'),wiki:textValue(data,'wiki')||wikiURL(name,'spell')};if(existing){if(c.concentration===existing.name)c.concentration=spell.name;Object.assign(existing,spell);}else c.spells.push(spell);modal.close();commit('A little more magic in your spellbook.');});}
function editSlots() {const c=character();setModal('Magic for the road ahead.',`<p class="modal-intro">Enter maximum slots for each spell level. Used slots are kept up to the new maximum. Tap slot squares in your spellbook to spend or restore them.</p><div class="form-grid">${select('Spellcasting ability (auto = class default)','spellAbility',['auto','int','wis','cha','str','dex','con'],c.spellAbility)}${c.slots.map((s,i)=>field('Level '+(i+1)+' maximum','slot'+i,s.max,'number','required min="0" max="20" step="1"')).join('')}</div><p class="form-help">Use the 2024 class rules to check your spell progression, including multiclass and pact magic rules.</p>${actions('Save slots')}`,data=>{c.spellAbility=textValue(data,'spellAbility');c.slots.forEach((s,i)=>{s.max=num(data,'slot'+i);s.used=Math.min(s.used,s.max);});modal.close();commit('Spell slots updated.');});}
function castSpell(id) {const c=character(),s=c.spells.find(s=>s.id===id);if(!s)return;const available=c.slots.map((slot,i)=>({slot,level:i+1})).filter(({slot,level})=>level>=s.level&&slot.used<slot.max);setModal(`Cast ${esc(s.name)}.`,`${s.concentration&&c.concentration?`<div class="concentration-banner">${icon('spark')}This will replace concentration on ${esc(c.concentration)}.</div>`:''}<p class="modal-intro">${s.level===0?'Cantrips don’t use a spell slot.':'Choose the slot you’re using. You can cast without a slot for rituals, scrolls, or a class feature if your table allows it.'}</p>${s.level>0?select('Cast using','slot',[...available.map(v=>'Level '+v.level),'No slot (ritual / item / feature)'],available[0]?'Level '+available[0].level:'No slot (ritual / item / feature)'):''}${s.notes?`<div class="detail-paragraph">${esc(s.notes)}</div>`:''}<p class="form-help">Apply the spell’s damage, healing, and other effects separately. ${ext(referenceURL(s.wiki,s.name,'spell'),'Read the full spell '+icon('external'))}</p>${actions('Cast spell')}`,data=>{if(s.level>0&&String(data.get('slot')).startsWith('Level ')){const i=Number(String(data.get('slot')).slice(6))-1;if(!c.slots[i]||c.slots[i].used>=c.slots[i].max)throw new Error('That slot is no longer available.');c.slots[i].used++;}if(s.concentration)c.concentration=s.name;modal.close();commit(`${s.name} cast.${s.concentration?' You’re concentrating.':''}`);});}

function rollBreakdown(r) {if(!r.rolls.length)return `Fixed result: ${r.total}`;return `${r.rolls.join(r.mode==='normal'?' + ':' & ')}${r.mode!=='normal'?` → ${r.mode==='advantage'?'higher':'lower'} die`:''}${r.bonus?' '+signed(r.bonus):''} = ${r.total}`;}
function performRoll(expression,label='Dice roll',mode='normal',inDialog=true,result=null,featureId='') {
  const r={...(result||rollDice(expression,mode)),label,time:Date.now()};lastRoll=r;rollHistory.unshift(r);rollHistory=rollHistory.slice(0,50);sound();
  if(inDialog)setModal(esc(label),`<div class="roll-modal"><div class="roll-expression">${esc(r.expression)}${mode!=='normal'?' · '+mode:''}</div><div class="big-die">${icon('dice')}<strong>${r.total}</strong></div>${r.natural===20?'<div class="roll-critical">✦ NATURAL 20! ✦</div>':r.natural===1?'<div class="roll-critical fail">NATURAL 1. A NEW PLOT TWIST.</div>':''}<div class="roll-breakdown">${esc(rollBreakdown(r))}</div></div><div class="modal-actions">${btn('close','Keep adventuring','btn')}${featureId?btn('feature-roll',icon('dice')+'Use & roll again','btn btn-primary',`data-id="${featureId}" ${character().features.some(f=>f.id===featureId&&f.maxUses&&f.used>=f.maxUses)?'disabled':''}`):btn('reroll',icon('dice')+'Roll again','btn btn-primary',`data-expression="${esc(expression)}" data-label="${esc(label)}" data-mode="${mode}"`)}</div>`);
  else {render();const die=$('#tray-die');die?.classList.add('rolling');setTimeout(()=>die?.classList.remove('rolling'),450);}
  return r;
}
function exportBackup() {const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`questlog-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Keep it somewhere safe.');}
function confirmDelete(type,id) {const c=character(),entry=c[type]?.find(v=>v.id===id);if(!entry)return;setModal('Leave this behind?',`<p class="modal-intro">Delete “${esc(entry.name||entry.title)}”? This can’t be undone. Export a backup first if you want to keep a copy.</p><div class="modal-actions">${btn('close','Keep it','btn')}${btn('confirm-delete',icon('trash')+'Delete','btn btn-danger',`data-type="${type}" data-id="${id}"`)}</div>`);}
function showInstall() {if(installPrompt){installPrompt.prompt();installPrompt.userChoice.finally(()=>{installPrompt=null;});return;}setModal('Your adventure, in your pocket.',`<p class="modal-intro">Open your hosted Questlog link on your phone, then add it to your home screen.</p><ul class="install-instructions"><li><strong>iPhone / iPad:</strong> In Safari, tap Share, then Add to Home Screen.</li><li><strong>Android:</strong> Open the browser menu, then Install app or Add to Home screen.</li><li>Visit once online and wait for “Ready for offline adventures.” before heading off the grid.</li></ul><p class="form-help">If you already installed Questlog, open it from your home screen. Device data stays local; export and import to move characters between browsers.</p><div class="modal-actions">${btn('close','Got it','btn btn-primary')}</div>`);}

document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  const action=el.dataset.action,id=el.dataset.id,c=character();
  try {
    switch(action){
      case 'navigate':if(modal.open)modal.close();navigate(el.dataset.route);break;
      case 'close':modal.close();break;
      case 'characters':showCharacters();break;
      case 'more':setModal('A little more adventure.',`<p class="modal-intro">Everything else you need for the road.</p>${btn('navigate',icon('compass')+'<div><strong>2024 compendium</strong><small>Classes, spells, gear, and more</small></div>'+icon('chevron'),'character-option','data-route="wiki"')}${btn('navigate',icon('settings')+'<div><strong>Settings & backup</strong><small>Export, import, and install</small></div>'+icon('chevron'),'character-option','data-route="settings"')}${btn('characters',icon('people')+'<div><strong>Your characters</strong><small>Switch, create, or edit a character</small></div>'+icon('chevron'),'character-option')}`);break;
      case 'switch-character':state.activeId=id;modal.close();query='';filter='All';commit('Ready when you are.');break;
      case 'demo-2024':{if(state.characters.length>=100){toast('This browser has 100 characters. Export a backup before removing any.',true);break;}const example=demoCharacter();example.name+=' (2024 example)';state.characters.push(example);state.activeId=example.id;navigate('sheet');commit('2024 example added. Your other characters are preserved.');break;}
      case 'default-party':{if(state.characters.length+3>100){toast('There is not enough room for three more characters. Export a backup before removing any.',true);break;}const party=defaultCharacters();state.characters.push(...party);state.activeId=party[0].id;modal.close();navigate('sheet');commit('Melchior, Balin, and Teyla added.');break;}
      case 'new-character':if(state.characters.length>=100){toast('This browser has 100 characters. Export a backup before removing any.',true);break;}editCharacter(true);break;
      case 'scan-sheet':if(state.characters.length>=100){toast('This browser has 100 characters. Export a backup before removing any.',true);break;}openSheetScanner({modal,setModal,onCreate:scanned=>{
        if(state.characters.length>=100)throw new Error('Questlog supports up to 100 characters per browser.');
        const next={...state,characters:[...state.characters,scanned],activeId:scanned.id};
        if(new Blob([JSON.stringify(next)]).size>2000000)throw new Error('This character would exceed the 2 MB save limit. Shorten the imported notes or remove entries.');
        state=next;query='';filter='All';route='sheet';location.hash='sheet';commit('Welcome to Questlog, '+scanned.name+'.');
      }});break;
      case 'edit-character':editCharacter();break;
      case 'portrait':editPortrait();break;
      case 'delete-character':setModal('End this chapter?',`<p class="modal-intro">Delete ${esc(c.name)} and all their notes, items, and spells? This can’t be undone. Export a backup to keep this story.</p><div class="modal-actions">${btn('close','Keep character','btn')}${btn('confirm-delete-character','Delete character','btn btn-danger')}</div>`);break;
      case 'confirm-delete-character':if(state.characters.length>1){state.characters=state.characters.filter(v=>v.id!==c.id);state.activeId=state.characters[0].id;modal.close();commit('Character removed.');}break;
      case 'sheet-collapse':toggleSheetSection(c,el.dataset.section);persist();renderChrome();refreshSheetLayout($('#main'),c);break;
      case 'sheet-favorite':{
        toggleSheetFavorite(c,el.dataset.section,el.dataset.entry);persist();renderChrome();refreshSheetLayout($('#main'),c);
        if(el.closest('[data-sheet-entry]')?.hidden)$('#main').querySelector(`[data-sheet-section="${el.dataset.section}"] .sheet-section-toggle`)?.focus({preventScroll:true});
        break;
      }
      case 'abilities':editAbilities();break;
      case 'combat-edit':editCombat();break;
      case 'personality':editSheetText('Your character, beyond the numbers.',['personalityTraits','ideals','bonds','flaws']);break;
      case 'proficiencies':editSheetText('The things you know.',['languages','armorProficiencies','weaponProficiencies','toolProficiencies']);break;
      case 'essentials':editEssentials();break;
      case 'ability-roll':performRoll(`1d20${signed(abilityCheckBonus(c,el.dataset.key))}`,ABILITIES[el.dataset.key]+' check');break;
      case 'initiative':performRoll(`1d20${signed(initiative(c))}`,'Roll for initiative',c.initiativeAdvantage?'advantage':'normal');break;
      case 'skill-roll':performRoll(`1d20${signed(skillBonus(c,el.dataset.skill))}`,el.dataset.skill+' check');break;
      case 'save-roll':performRoll(`1d20${signed(saveBonus(c,el.dataset.key))}`,ABILITIES[el.dataset.key]+' saving throw');break;
      case 'skill-prof':{const key=el.dataset.skill;if(c.expertise.includes(key)){c.expertise=c.expertise.filter(s=>s!==key);c.skills=c.skills.filter(s=>s!==key);}else if(c.skills.includes(key))c.expertise.push(key);else c.skills.push(key);commit();break;}
      case 'save-prof':{const key=el.dataset.key;c.saves=c.saves.includes(key)?c.saves.filter(k=>k!==key):[...c.saves,key];commit();break;}
      case 'hp':showHP(el.dataset.kind);break;
      case 'hp-apply':{const form=$('#modal-form');if(form.reportValidity())applyHP(new FormData(form),el.dataset.kind);break;}
      case 'inspiration':c.inspiration=!c.inspiration;commit(c.inspiration?'Heroic Inspiration ready: reroll one die immediately after rolling it.':'Heroic Inspiration spent: use the new die roll.');break;
      case 'conditions':showConditions();break;
      case 'condition':{const v=el.dataset.condition;c.conditions=c.conditions.includes(v)?c.conditions.filter(x=>x!==v):[...c.conditions,v];el.classList.toggle('active');el.setAttribute('aria-pressed',String(c.conditions.includes(v)));el.innerHTML=esc(v)+(c.conditions.includes(v)?icon('check'):'');persist();render();break;}
      case 'death-counter':c[el.dataset.kind==='success'?'deathSuccess':'deathFailure']=Number(el.dataset.value);commit();break;
      case 'death-roll':{if(c.hp>0||c.deathSuccess>=3||c.deathFailure>=3)break;const r=performRoll(`1d20${signed(-exhaustionPenalty(c))}`,'Death saving throw');if(r.natural===20){changeHP(c,1,'heal');toast('Natural 20! You regain 1 HP.');}else if(r.total>=10)c.deathSuccess=Math.min(3,c.deathSuccess+1);else c.deathFailure=Math.min(3,c.deathFailure+(r.natural===1?2:1));commit();break;}
      case 'rest':showRest(el.dataset.kind);break;
      case 'xp':showXP();break;
      case 'level-up':showLevelUp();break;
      case 'item':editItem(id);break;
      case 'currency':editCurrency();break;
      case 'quantity':{const item=c.items.find(i=>i.id===id);item.qty=clamp(item.qty+Number(el.dataset.delta),0,99999);commit();break;}
      case 'equip':{const item=c.items.find(i=>i.id===id);item.equipped=!item.equipped;commit();break;}
      case 'use-item':{const item=c.items.find(i=>i.id===id);if(!item||item.qty<1)break;setModal(`Use ${esc(item.name)}?`,`<p class="modal-intro">This will use one item from your pack. ${/^potion of healing$/i.test(item.name)?'As a Bonus Action, drink it to roll 2d4 + 2 and restore that much HP to this character.':'Apply its effects at the table.'}</p><div class="modal-actions">${btn('close','Save it','btn')}${btn('confirm-use-item','Use item','btn btn-primary',`data-id="${id}"`)}</div>`);break;}
      case 'confirm-use-item':{const item=c.items.find(i=>i.id===id);if(!item||item.qty<1)break;item.qty--;if(/^potion of healing$/i.test(item.name)){const r=performRoll('2d4+2','Potion of healing');changeHP(c,r.total,'heal');commit(`${r.total} healing. A little better already.`);}else{modal.close();commit(item.name+' used.');}break;}
      case 'note':editNote(id);break;
      case 'view-note':viewNote(id);break;
      case 'pin-note':{const n=c.notes.find(n=>n.id===id);n.pinned=!n.pinned;commit(n.pinned?'Note pinned to your sheet.':'Note unpinned.');break;}
      case 'attack':editAttack(id);break;
      case 'attack-roll':{const a=c.attacks.find(a=>a.id===id);performRoll(`1d20${signed(attackBonus(c,a))}`,a.name+' · to hit',a.rollMode);break;}
      case 'damage-roll':{const a=c.attacks.find(a=>a.id===id);performRoll(a.damage,a.name+' · damage');break;}
      case 'feature':editFeature(id);break;
      case 'feature-roll':{const f=c.features.find(f=>f.id===id);if(!f?.rollFormula)break;const result=rollFeature(f);performRoll(f.rollFormula,f.name,'normal',true,result,f.id);commit();break;}
      case 'feature-use':{const f=c.features.find(f=>f.id===id);f.used=clamp(Number(el.dataset.used),0,f.maxUses);commit();break;}
      case 'spell':editSpell(id);break;
      case 'prepare':{const s=c.spells.find(s=>s.id===id);s.prepared=!s.prepared;commit();break;}
      case 'slots':editSlots();break;
      case 'slot':{const slot=c.slots[Number(el.dataset.level)];slot.used=clamp(Number(el.dataset.used),0,slot.max);commit();break;}
      case 'cast':castSpell(id);break;
      case 'end-concentration':c.concentration='';commit('Concentration ended.');break;
      case 'filter':filter=el.dataset.filter;render();break;
      case 'select-die':diceExpression='1d'+el.dataset.sides;if(el.dataset.sides!=='20')rollMode='normal';render();break;
      case 'roll-mode':diceExpression=$('#dice-expression').value;rollMode=el.dataset.mode;render();break;
      case 'reroll':performRoll(el.dataset.expression,el.dataset.label,el.dataset.mode);break;
      case 'clear-rolls':rollHistory=[];render();break;
      case 'delete-entry':confirmDelete(el.dataset.type,id);break;
      case 'confirm-delete':{const type=el.dataset.type;if(!['items','notes','spells','attacks','features'].includes(type))break;const entry=c[type].find(v=>v.id===id);if(type==='spells'&&entry?.name===c.concentration)c.concentration='';c[type]=c[type].filter(v=>v.id!==id);const section={items:'pack',notes:'journal',attacks:'attacks',features:'features'}[type];if(section&&isSheetFavorite(c,section,id))toggleSheetFavorite(c,section,id);modal.close();commit('Removed from your journal.');break;}
      case 'export':exportBackup();break;
      case 'import':$('#import-file').click();break;
      case 'confirm-import':{const incoming=modal._incoming;if(!incoming)break;incoming.characters.forEach(x=>{if(state.characters.some(c=>c.id===x.id)){x.id=uid();x.name=x.name.slice(0,110)+' (imported)';}state.characters.push(x);});state.activeId=incoming.characters[0].id;delete modal._incoming;modal.close();commit(`${incoming.characters.length} character${incoming.characters.length===1?'':'s'} added. Welcome back.`);break;}
      case 'sound':state.settings.sound=!state.settings.sound;commit();sound();break;
      case 'install':showInstall();break;
      case 'recover-storage':setModal('Save this sheet on this device?',`<p class="modal-intro">This replaces the unreadable Questlog data stored in this browser with your current characters. Export a backup of your current sheet first if you need it.</p><div class="modal-actions">${btn('close','Cancel','btn')}${btn('confirm-recover-storage','Replace saved data','btn btn-danger')}</div>`);break;
      case 'confirm-recover-storage':storageBlocked=false;modal.close();commit('Saving enabled for this sheet.');break;
    }
  }catch(error){toast(error.message||'That action couldn’t be completed.',true);}
});
document.addEventListener('submit',event=>{
  if(event.target.id==='modal-form'){event.preventDefault();if(!modalSubmit)return;try{for(const input of event.target.querySelectorAll('input[required][type="text"]')){if(!input.value.trim())throw new Error('Please fill in '+(input.closest('label')?.firstChild.textContent||'all required fields')+'.');}modalSubmit(new FormData(event.target));}catch(error){const el=$('#form-error');el.hidden=false;el.className='form-error';el.textContent=error.message;}}
  if(event.target.id==='dice-form'){event.preventDefault();try{diceExpression=$('#dice-expression').value;performRoll(diceExpression,'Custom roll',rollMode,false);}catch(error){toast(error.message,true);}}
});
document.addEventListener('input',event=>{if(event.target.dataset.catalogSearch)handleCatalogFilter(modal,event.target,character());if(event.target.hasAttribute('data-feature-level'))handleCatalogChoice(modal,event.target,character());if(event.target.id==='search'){query=event.target.value;const start=event.target.selectionStart;render();const input=$('#search');input.focus({preventScroll:true});try{input.setSelectionRange(start,start);}catch{}}});
document.addEventListener('change',event=>{
  if(modal.contains(event.target))handleCatalogChoice(modal,event.target,character());
  if(event.target.matches('[data-reference-kind], [data-reference-entry]'))updateCatalogBrowser($('#main'),event.target.hasAttribute('data-reference-kind'));
});
document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.dataset.catalogSearch)event.preventDefault();});
$('#import-file').addEventListener('change',async event=>{
  const file=event.target.files[0];event.target.value='';if(!file)return;
  try{if(file.size>2000000)throw new Error('Choose a backup smaller than 2 MB.');const incoming=parseBackup(await file.text());if(state.characters.length+incoming.characters.length>100)throw new Error('Questlog supports up to 100 characters per browser.');modal._incoming=incoming;setModal('Bring your adventures along.',`<p class="modal-intro">Add ${incoming.characters.length} character${incoming.characters.length===1?'':'s'} from this backup? Your existing characters will be kept. Matching characters will be added as separate imported copies.</p>${incoming.characters.map(c=>`<div class="character-option"><span class="mini-avatar">${portraitMarkup(c)}</span><div><strong>${esc(c.name)}</strong><small>Level ${c.level} ${esc(c.class)} · ${c.notes.length} notes · ${c.items.length} items</small></div></div>`).join('')}<div class="modal-actions">${btn('close','Cancel','btn')}${btn('confirm-import','Import characters','btn btn-primary')}</div>`);}catch(error){toast(error.message,true);}
});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(Object.hasOwn(routes,next)&&next!==route){route=next;query='';filter='All';render();window.scrollTo(0,0);}});
// Other tabs can edit the same browser data. Refresh without silently overwriting them.
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY&&event.newValue){try{const incoming=parseBackup(event.newValue);state=incoming;if(modal.open)modal.close();render();toast('Sheet refreshed with changes from another tab.');}catch{toast('Another tab saved unreadable data. Export your current sheet.',true);storageBlocked=true;}}});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
if(!storageBlocked)persist();
render();
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{scope:'./',type:'module'}).then(reg=>{const ready=()=>{if(!sessionStorage.getItem('questlog-offline-ready')){toast('Ready for offline adventures.');sessionStorage.setItem('questlog-offline-ready','1');}};if(reg.active)ready();else reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='activated')ready();});});}).catch(()=>{/* The tracker still works without installation; show local storage status separately. */});
